-- T-Lab reference catalog data, extracted exactly from public/tlab_db_complete_v7.sql on main.
-- For an existing, backed-up local TEST database only. Never run on patient/production DB.
-- Original source contains DROP/TRUNCATE/REPLACE; those destructive operations are excluded.
-- Four data sets only: scientific_departments, doctor_specialties, lab_tests, test_parameters.
-- INSERT IGNORE preserves rows with existing identical PRIMARY KEY IDs; no deletes/overwrites.
-- A code with a different ID is not automatically deduplicated: inspect codes before import.
-- Clinical reference intervals and critical limits are imported as legacy source data;
-- they are NOT clinically validated or approved for patient reports.
-- Keep the backup and test first. If any MySQL warning occurs, inspect it before using the catalog.
SET NAMES utf8;
USE `tlab_local_test`;
START TRANSACTION;

-- scientific_departments (10 original rows)

-- doctor_specialties (12 original rows)

-- lab_tests (106 original rows)

-- test_parameters (414 original rows)

COMMIT;

-- Read-only verification (expected counts on an otherwise empty catalog):
SELECT 'scientific_departments' AS catalog, COUNT(*) AS records FROM scientific_departments
UNION ALL SELECT 'doctor_specialties', COUNT(*) FROM doctor_specialties
UNION ALL SELECT 'lab_tests', COUNT(*) FROM lab_tests
UNION ALL SELECT 'test_parameters', COUNT(*) FROM test_parameters;
